import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.C2TvIV46.js";const u=JSON.parse('{"title":"コンパイラ設定","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/compiler-settings.md","filePath":"ja/language/compiler-settings.md"}'),l={name:"ja/language/compiler-settings.md"};function r(c,e,n,g,i,s){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="コンパイラ設定" tabindex="-1">コンパイラ設定 <a class="header-anchor" href="#コンパイラ設定" aria-label="Permalink to &quot;コンパイラ設定&quot;">​</a></h1><p>Megalo ソースはこれらのオプションを宣言しません — コンパイラがスクリプトをどれだけ厳しく解釈するかを変える <strong>コンパイル時スイッチ</strong> です。同じ <code>.txt</code> でも、エディタが使うモードによってエラー、警告、変数割り当ての結果が変わります。</p><p>HREK の <strong>MegaloEdit</strong> は常に <strong>寛容モード</strong>（許容的な既定値）でコンパイルします。Bungie の内部ビルドファームはおそらくより厳格な設定を使っていました。スイッチは <strong>ManagedMegalo.dll</strong>（<code>ParsingHelper</code>、<code>MegaloCompiler</code>）にあり、MegaloEdit は配線していますが UI には露出していません。</p><p>MegaloEdit は <strong>入力</strong> と <strong>出力ディレクトリ</strong> 設定（ファイル → 設定）も公開しています。これらのパスは外部ファイルの解決場所を制御します。</p><table tabindex="0"><thead><tr><th>設定</th><th>解決に使うとき</th></tr></thead><tbody><tr><td><strong>入力ディレクトリ</strong></td><td><a href="/MegaloEvolved/beta/docs/ja/language/elements/include"><code>include</code></a> と <a href="/MegaloEvolved/beta/docs/ja/language/elements/localized-include"><code>localized_include</code></a> のパス</td></tr><tr><td><strong>出力ディレクトリ</strong></td><td>コンパイル済み <code>.mglo</code> への <a href="/MegaloEvolved/beta/docs/ja/language/elements/base"><code>base</code></a> 参照</td></tr></tbody></table><p>ソース内の include パスは入力ディレクトリ（およびインクルード元ファイル）からの相対です。ベースパスは出力ディレクトリ内のコンパイル済みバリアント名 — MegaloEdit.exe では既定で HREK インストール下の <code>maps/megalo</code> — です。参照する派生をビルドする前に親スクリプトをコンパイルして <code>.mglo</code> を用意してください。<a href="/MegaloEvolved/beta/docs/ja/language/base-files">ベースファイル</a> を参照。</p><h2 id="localized-include-の厳格さ" tabindex="-1">localized_include の厳格さ <a class="header-anchor" href="#localized-include-の厳格さ" aria-label="Permalink to &quot;localized_include の厳格さ&quot;">​</a></h2><p>欠けた <a href="/MegaloEvolved/beta/docs/ja/language/elements/localized-include"><code>localized_include</code></a> を省略可能にするか致命的にするかを制御します。</p><table tabindex="0"><thead><tr><th>モード</th><th>ファイル欠損時の挙動</th></tr></thead><tbody><tr><td><strong>寛容</strong>（MegaloEdit）</td><td>警告、include をスキップ — コンパイル続行</td></tr><tr><td><strong>厳格</strong></td><td>ハードエラー。欠けたプレーン <a href="/MegaloEvolved/beta/docs/ja/language/elements/include"><code>include</code></a> と同じ</td></tr></tbody></table><p>ファイルが存在する場合、両モードの挙動は同じです。</p><p>MegaloEdit は常に寛容モードを使います。<a href="/MegaloEvolved/beta/docs/ja/language/elements/localized-include"><code>localized_include</code></a> を参照。</p><p><em>ManagedMegalo.dll: <code>ParsingHelper</code> 上の <code>enforceLocalizedIncludes</code>。</em></p><h2 id="文字列リテラルの厳格さ" tabindex="-1">文字列リテラルの厳格さ <a class="header-anchor" href="#文字列リテラルの厳格さ" aria-label="Permalink to &quot;文字列リテラルの厳格さ&quot;">​</a></h2><p>文字列テーブル記号が期待される箇所で <strong>引用リテラル文字列</strong> を許すかどうかを制御します。</p><p>多くの要素は文字列テーブルトークンを要求します — <code>engine_data name &quot;Slayer&quot;</code> ではなく <code>engine_data name slayer_title</code>。寛容モードではリテラルでもコンパイルできますが警告が出ます。</p><blockquote><p><em>You used a literal string &#39;…&#39;. Fix this before you submit. The build farm enforces localization.</em></p></blockquote><p>厳格モードでは同じリテラルは <strong>ハードエラー</strong> です。厳格モードはパーサーがローカライズを強制している箇所での引用文字列もブロックします。</p><p>MegaloEdit は常に寛容モードを使います。出荷 Reach スクリプトは一貫して文字列テーブル記号を使います。</p><p><em>ManagedMegalo.dll: <code>ParsingHelper</code> 上の <code>enforceLocalization</code>。</em></p><h2 id="一時変数のオーバーフロー" tabindex="-1">一時変数のオーバーフロー <a class="header-anchor" href="#一時変数のオーバーフロー" aria-label="Permalink to &quot;一時変数のオーバーフロー&quot;">​</a></h2><p><strong><code>temporary</code></strong> は、トリガーまたは <code>for_each</code> ブロック内で <code>temporary</code> キーワードにより宣言するスクラッチ変数です。そのブロック実行の間だけ存在し — 永続的な <a href="/MegaloEvolved/beta/docs/ja/language/elements/variables"><code>variables</code></a> スロットを宣言せずにゲッター結果や中間値を保持するのに便利です。<a href="/MegaloEvolved/beta/docs/ja/language/variable-model#temporary-variables">変数モデル — 一時変数</a> を参照。</p><p>一時変数の割り当ては Megalo バージョンごとに変わっています。</p><ul><li><strong>当初</strong> — <code>temporary</code> 導入時、コンパイラは一時変数を <strong>グローバル変数</strong> として扱い、グローバル変数プールから直接割り当てていました。</li><li><strong>Halo 4</strong> — <strong>専用の一時変数プール</strong> を追加し、グローバルを消費せずにトリガーが使えるスクラッチ変数を実質的に増やしました。</li><li><strong>Reach MCC</strong> — その別プールが Halo 4 から <strong>バックポート</strong> されました。Xbox 360 TU1 Reach は依然として当初のグローバル対応付けです。</li></ul><p>このオーバーフロー設定は Megalo バージョンが <strong>Xbox 360 TU1 より後</strong>（Reach MCC 以降）の場合にのみ適用されます。TU1 では一時変数はすでにグローバルにマップされるため、オーバーフロー元となる別プールはありません。</p><p>MCC Reach では、各 <a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger#action-scope">アクションスコープ</a> に型ごとの固定された専用一時プールがあります。スコープあたり:</p><table tabindex="0"><thead><tr><th>型</th><th>専用プール</th><th>グローバルへの最大オーバーフロー</th></tr></thead><tbody><tr><td><code>number</code></td><td>10</td><td>12</td></tr><tr><td><code>object</code></td><td>8</td><td>16</td></tr><tr><td><code>team</code></td><td>6</td><td>8</td></tr><tr><td><code>player</code></td><td>3</td><td>8</td></tr></tbody></table><p>オーバーフローが <strong>有効</strong>（MegaloEdit 既定）のとき、専用プールが満杯になるとコンパイラは余剰の一時変数を同型の <strong>未使用グローバル変数スロット</strong> へ、オーバーフロー上限まで溢れさせられます。オーバーフローが <strong>無効</strong> のとき、一時スロット不足はコンパイル失敗になります。</p><p>これは 1 つのスコープにどれだけロジックを詰められるかに影響します — 構文ではなく、深く入れ子の <code>temporary</code> 宣言が受理されるかどうかです。スコープ入れ子と TU1 の挙動は <a href="/MegaloEvolved/beta/docs/ja/versions/107-mcc/#limits">107 (MCC) — Limits</a> と <a href="/MegaloEvolved/beta/docs/ja/versions/107/#limits">107 — Limits</a> を参照。</p><p><em>ManagedMegalo.dll: <code>MegaloCompiler</code> 上の <code>TemporaryVariablesCanOverflowIntoUnusedGlobalVariables</code>。</em></p><p><a href="/MegaloEvolved/beta/docs/ja/guide/megalo-versions">Megalo バージョン</a>（MCC と TU1）も参照。</p><h2 id="まとめ" tabindex="-1">まとめ <a class="header-anchor" href="#まとめ" aria-label="Permalink to &quot;まとめ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>設定</th><th>寛容（MegaloEdit）</th><th>厳格</th><th>言語機能</th></tr></thead><tbody><tr><td>入力ディレクトリ</td><td>—</td><td>—</td><td><a href="/MegaloEvolved/beta/docs/ja/language/elements/include"><code>include</code></a>、<a href="/MegaloEvolved/beta/docs/ja/language/elements/localized-include"><code>localized_include</code></a></td></tr><tr><td>出力ディレクトリ</td><td>—</td><td>—</td><td><a href="/MegaloEvolved/beta/docs/ja/language/elements/base"><code>base</code></a>（<code>.mglo</code> 検索）</td></tr><tr><td>ローカライズ include</td><td>欠損 → 警告</td><td>欠損 → エラー</td><td><a href="/MegaloEvolved/beta/docs/ja/language/elements/localized-include"><code>localized_include</code></a></td></tr><tr><td>文字列リテラル</td><td>警告</td><td>エラー</td><td>文字列テーブル記号 vs <code>&quot;quoted&quot;</code> テキスト</td></tr><tr><td>一時変数オーバーフロー（MCC+）</td><td>空きグローバルへ溢れ</td><td>プール満杯でコンパイル失敗</td><td>トリガー内の <a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger#action-scope"><code>temporary</code></a></td></tr></tbody></table><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/base-files">ベースファイル</a> — 派生スクリプトと <code>.mglo</code> 検索</li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/localized-include"><code>localized_include</code></a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/syntax#includes">構文 — Includes</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger#action-scope">trigger — アクションスコープ</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/variable-model#temporary-variables">変数モデル — 一時変数</a></li><li><a href="/MegaloEvolved/beta/docs/ja/guide/megalo-versions">Megalo バージョン</a> — MCC と Xbox 360 TU1</li></ul>',34)])])}const b=a(l,[["render",r]]);export{u as __pageData,b as default};
